fn format_tags(tags: &[&str]) -> String {
    let mut out = String::new();
    for tag in tags {
        let bracketed = "[" + tag + "]";
        out.push_str(&bracketed);
    }
    out
}

fn format_tags(tags: &[&str]) -> String {
    let mut out = String::new();
    for tag in tags {
        out = format!("{out}<{tag}>");
    }
    out
}

